css:
.cade-eu-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}
.cade-eu-sim-header {
    background: linear-gradient(135deg, #0a1f3d 0%, #122d57 100%);
    color: #f4f5f7;
    border-radius: 4px;
    padding: 24px 32px;
    margin-bottom: 24px;
    border-left: 4px solid #c9a961;
}
.cade-eu-sim-header-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
}
.cade-eu-sim-header h1 {
    margin: 0;
    font-size: 1.5rem;
    font-weight: 600;
    letter-spacing: 0.02em;
    color: #ffffff;
}
.cade-eu-sim-subtitle {
    margin-top: 6px;
    font-size: 0.85rem;
    color: #c9a961;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}
.cade-eu-sim-clock {
    display: flex;
    gap: 16px;
}
.cade-eu-sim-clock-item {
    background: rgba(201,169,97,0.12);
    border: 1px solid rgba(201,169,97,0.4);
    border-radius: 4px;
    padding: 10px 16px;
    text-align: right;
}
.cade-eu-sim-clock-label {
    display: block;
    font-size: 0.7rem;
    color: #c9a961;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.cade-eu-sim-clock-value {
    font-size: 1.4rem;
    font-weight: 700;
    color: #ffffff;
}
.cade-eu-sim-briefing {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-left: 4px solid #0a1f3d;
    border-radius: 4px;
    padding: 22px 28px;
    margin-bottom: 24px;
}
.cade-eu-sim-briefing-tag {
    display: inline-block;
    background: #0a1f3d;
    color: #c9a961;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    padding: 3px 10px;
    border-radius: 2px;
    margin-bottom: 10px;
}
.cade-eu-sim-briefing h2 {
    margin: 0 0 6px 0;
    font-size: 1.2rem;
    font-weight: 600;
    color: #0a1f3d;
}
.cade-eu-sim-briefing-sub {
    font-size: 0.82rem;
    color: #5a687e;
    margin-bottom: 12px;
    font-style: italic;
}
.cade-eu-sim-briefing p {
    margin: 0;
    font-size: 0.92rem;
    line-height: 1.55;
    color: #1a2744;
}
.cade-eu-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 12px;
    margin-bottom: 24px;
}
.cade-eu-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    padding: 16px 18px;
    border-top: 3px solid #5a687e;
}
.cade-eu-sim-kpi-cade { border-top-color: #1d4e89; }
.cade-eu-sim-kpi-eu { border-top-color: #003399; }
.cade-eu-sim-kpi-give { border-top-color: #b91c1c; }
.cade-eu-sim-kpi-syn { border-top-color: #166534; }
.cade-eu-sim-kpi-irr { border-top-color: #c9a961; }
.cade-eu-sim-kpi-chair { border-top-color: #5b21b6; }
.cade-eu-sim-kpi-counsel { border-top-color: #0f766e; }
.cade-eu-sim-kpi-label {
    font-size: 0.68rem;
    color: #5a687e;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.cade-eu-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #0a1f3d;
    line-height: 1.1;
}
.cade-eu-sim-controls {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
}
.cade-eu-sim-controls h3 {
    margin: 0 0 18px 0;
    font-size: 1rem;
    font-weight: 600;
    color: #0a1f3d;
    padding-bottom: 10px;
    border-bottom: 1px solid #e4e7ec;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.cade-eu-sim-decision {
    margin-bottom: 16px;
}
.cade-eu-sim-decision label {
    display: block;
    font-size: 0.82rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
}
.cade-eu-sim-controls select,
.cade-eu-sim-controls input {
    background: #ffffff;
    border: 1px solid #c4cbd8;
    color: #1a2744;
    border-radius: 3px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
}
.cade-eu-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}
.cade-eu-sim-controls select:focus,
.cade-eu-sim-controls input:focus {
    outline: none;
    border-color: #0a1f3d;
    box-shadow: 0 0 0 2px rgba(10,31,61,0.1);
}
.cade-eu-sim-button-row {
    margin-top: 22px;
    padding-top: 18px;
    border-top: 1px solid #e4e7ec;
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
}
.cade-eu-sim-button-row .btn-primary {
    background: #0a1f3d;
    border-color: #0a1f3d;
    color: #ffffff;
    padding: 10px 22px;
    font-size: 0.88rem;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    border-radius: 3px;
    transition: background 0.2s ease;
}
.cade-eu-sim-button-row .btn-primary:hover {
    background: #122d57;
    border-color: #122d57;
}
.cade-eu-sim-button-row .btn-outline-secondary {
    border-color: #c4cbd8;
    color: #5a687e;
    border-radius: 3px;
    padding: 8px 16px;
}
.cade-eu-sim-history-wrap,
.cade-eu-sim-chart-wrap {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    padding: 22px 28px;
    margin-bottom: 24px;
}
.cade-eu-sim-history-wrap h3,
.cade-eu-sim-chart-wrap h3 {
    margin: 0 0 16px 0;
    font-size: 1rem;
    font-weight: 600;
    color: #0a1f3d;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.cade-eu-sim-history-wrap table {
    font-size: 0.85rem;
    color: #1a2744;
}
.cade-eu-sim-history-wrap table thead th {
    background: #0a1f3d;
    color: #c9a961;
    border: none;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 10px 12px;
}
.cade-eu-sim-history-wrap table tbody td {
    border-bottom: 1px solid #e4e7ec;
    padding: 10px 12px;
}
.cade-eu-sim-chart-canvas {
    position: relative;
    height: 340px;
}
@media (max-width: 768px) {
    .cade-eu-sim-container { padding: 16px; }
    .cade-eu-sim-header { padding: 18px 20px; }
    .cade-eu-sim-header h1 { font-size: 1.15rem; }
    .cade-eu-sim-kpi-value { font-size: 1.4rem; }
    .cade-eu-sim-controls,
    .cade-eu-sim-briefing,
    .cade-eu-sim-history-wrap,
    .cade-eu-sim-chart-wrap { padding: 16px; }
    .cade-eu-sim-chart-canvas { height: 260px; }
}

/* --- EQIL additions (adapter 1.1.0) --- */
.cade-eu-sim-analysis {
    background: #ffffff;
    border: 1px solid #d9dde4;
    border-left: 4px solid #0a1f3d;
    border-radius: 4px;
    padding: 16px 20px;
    margin-bottom: 18px;
}
.cade-eu-sim-analysis-label {
    font-size: 0.72rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: #5a687e;
    font-weight: 600;
    margin-bottom: 6px;
}
.cade-eu-sim-analysis-body { font-size: 0.93rem; line-height: 1.6; color: #0a1f3d; }
.cade-eu-sim-analysis-body ul { margin: 0; padding-left: 20px; }
.cade-eu-sim-analysis-body li { margin-bottom: 6px; }
.cade-eu-sim-complete-banner {
    margin: 12px 0;
    padding: 12px 16px;
    border-radius: 4px;
    border: 1px solid #0a1f3d;
    background: #eef1f6;
    color: #0a1f3d;
    font-weight: 600;
}
button:focus-visible, select:focus-visible, input:focus-visible {
    outline: 3px solid #0a1f3d;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .cade-eu-sim-shell *, .cade-eu-sim-analysis, .cade-eu-sim-header {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

