                    board_defense: 'portfolio_reframe',
                    counsel_strategy: 'hold_eu_line',
                    coordination: 'full_icn'
                };
            }
            ['clearanceHistory', 'ebitdaHistory', 'synergyHistory', 'irrHistory'].forEach(function(k) {
                if (!Array.isArray(state.domainState[k])) state.domainState[k] = [];
            });
            var self = this;
            setTimeout(function() {
                self._syncControlsFromDecisions(state);
                self._updateBriefing(state);
                self._applyEndState((state && state.currentPeriod) ? state.currentPeriod : 1);
                if (state.domainState && state.domainState.lastAnalysis) {
                    var ana = document.getElementById('analysisDisplay');
                    if (ana) ana.innerHTML = state.domainState.lastAnalysis;
                }
            }, 50);
        }

        validateDecisions(decisions) {
            var round = (window.mySimulation && window.mySimulation.state)
                ? window.mySimulation.state.currentPeriod : 1;
            if (round === 1) {
                var pm = document.getElementById('productMarketSelect');
                var eg = document.getElementById('euGeoSelect');
                var ct = document.getElementById('cadeTheorySelect');
                if (pm) decisions.product_market = pm.value;
                if (eg) decisions.eu_geo = eg.value;
                if (ct) decisions.cade_theory = ct.value;
            } else if (round === 2) {
                var cr = document.getElementById('cadeRemedySelect');
                var er = document.getElementById('euRemedySelect');
                var ov = document.getElementById('overlaySelect');
                if (cr) decisions.cade_remedy = cr.value;
                if (er) decisions.eu_remedy = er.value;
                if (ov) decisions.overlay = ov.value;
            } else if (round === 3) {
                var bd = document.getElementById('boardDefenseSelect');
                var cs = document.getElementById('counselSelect');
                var co = document.getElementById('coordinationSelect');
                if (bd) decisions.board_defense = bd.value;
                if (cs) decisions.counsel_strategy = cs.value;
                if (co) decisions.coordination = co.value;
            }
            return true;
        }

        calculateResults(state) {
            var r = this._computeRound(state);
            return {
                period: r.period,
                roundName: r.roundName,
                roundKey: r.roundKey,
                cadeClearance: r.cadeClearance,
                euClearance: r.euClearance,
                ebitdaGiveup: r.ebitdaGiveup,
                synergyRetention: r.synergyRetention,
                chairManuel: r.chairManuel,
                counselTrust: r.counselTrust,
                dealIRR: r.dealIRR,
                branchSignal: r.branchSignal,
                composite: r.composite,
                overallScore: r.composite,
                totalScore: r.composite,
                score: r.composite
            };
        }

        _computeRound(state) {
            var round = state.currentPeriod;
            var d = state.decisions;
            var ds = state.domainState;

            var dCade = 0, dEu = 0, dGiveup = 0, dSynergy = 0, dBoard = 0, dChair = 0, dCounsel = 0;
            var notes = [];
            var branchSignal = '';

            if (round === 1) {
                if (d.product_market === 'single') {
                    dCade += 5; dEu += 3;
                    notes.push(this._L('Premium-cuts framing aligns with EU HMG paras 14-21 and CADE Res 9/2013 Art 8.', 'El encuadre de cortes premium se alinea con las Directrices horizontales de la UE párrafos 14-21 y con el art. 8 de la Res. 9/2013 del CADE.'));
                } else {
                    dCade -= 4; dEu -= 6;
                    notes.push(this._L('Broad product market understates competitive overlap; both regulators will reject.', 'Un mercado de producto amplio subestima el solapamiento competitivo; ambos reguladores lo rechazarán.'));
                }
                if (d.eu_geo === 'eu_wide') {
                    dEu += 8; dCounsel -= 5;
                    notes.push(this._L('EU-wide framing maximises HHI safe-harbour but Vacher-Lamoureux flags exposure on the Iberian SSNIP question.', 'El encuadre a escala UE maximiza el puerto seguro de HHI, pero Vacher-Lamoureux advierte exposición en la cuestión SSNIP ibérica.'));
                    branchSignal += 'C';
                } else if (d.eu_geo === 'multistate') {
                    dEu += 12; dCounsel += 4;
                    notes.push(this._L('Iberia + France + BeNeLux frame is defensible and counsel-aligned.', 'El marco Iberia más Francia más Benelux es defendible y está alineado con los abogados.'));
                    branchSignal += 'B';
                } else {
                    dEu -= 8; dGiveup += 4;
                    notes.push(this._L('Conceding the narrow Iberian frame triggers a heavier remedy ask on the EU side.', 'Conceder el marco ibérico estrecho provoca una petición de remedios más dura por el lado de la UE.'));
                    branchSignal += 'A';
                }
                if (d.cade_theory === 'contest_full') {
                    dCade -= 12; dCounsel -= 8;
                    notes.push(this._L('Contesting input-foreclosure end-to-end is high-variance; Caldas-Bittencourt warns CADE Tribunal post-2018 disfavours this posture.', 'Disputar el cierre de insumos de principio a fin es de alta varianza; Caldas-Bittencourt advierte que el Tribunal del CADE posterior a 2018 desfavorece esta postura.'));
                    branchSignal += 'C';
                } else if (d.cade_theory === 'contest_partial') {
                    dCade += 8; dCounsel += 6;
                    notes.push(this._L('Acknowledging the Salop-Scheffman frame while disputing magnitude is the defensible pivot.', 'Reconocer el marco de Salop-Scheffman y discutir la magnitud es el giro defendible.'));
                    branchSignal += 'B';
                } else {
                    dCade += 4; dGiveup += 3;
                    notes.push(this._L('Conceding the foreclosure theory simplifies posture but commits the room to a structural fix.', 'Conceder la teoría del cierre simplifica la postura pero compromete a la sala a un remedio estructural.'));
                    branchSignal += 'A';
                }
            } else if (round === 2) {
                if (d.cade_remedy === 'full_divest') {
                    dCade += 28; dGiveup += 14; dSynergy -= 21;
                    notes.push(this._L('Full Brazilian wholesale divestiture: clean structural cure (mirrors Bovitra/Pecuasul 2010) but heavy EBITDA hit.', 'Desinversión total del mayorista brasileño: remedio estructural limpio (replica Bovitra/Pecuasul 2010) pero con fuerte impacto en EBITDA.'));
                    branchSignal += 'A';
                } else if (d.cade_remedy === 'partial_mfn') {
                    dCade += 24; dGiveup += 9; dSynergy -= 9;
                    notes.push(this._L('Partial divestiture + MFN overlay: belt-and-braces against the Bevilacqua-Moraes RRC theory.', 'Desinversión parcial más capa de nación más favorecida: doble cinturón frente a la teoría de encarecimiento de costes rivales de Bevilacqua-Moraes.'));
                    branchSignal += 'B';
                } else {
                    dCade -= 32; dGiveup += 1;
                    notes.push(this._L('Behavioural-only at CADE: 60-70% probability of failing per Caldas-Bittencourt; Tribunal escalation risk live.', 'Solo remedios de conducta ante el CADE: probabilidad de fracaso del 60-70% según Caldas-Bittencourt; el riesgo de escalada al Tribunal está vivo.'));
                    branchSignal += 'C';
                }
                if (d.eu_remedy === 'structural_carve') {
                    dEu += 20; dGiveup += 6; dSynergy -= 5; dCounsel += 4;
                    notes.push(this._L('Iberian export-contract carve-out reassures Kalogridaki but signals weakness on the wider geographic market.', 'La exclusión de contratos de exportación ibéricos tranquiliza a Kalogridaki pero muestra debilidad en el mercado geográfico amplio.'));
                    branchSignal += 'A';
                } else if (d.eu_remedy === 'price_coord') {
                    dEu += 16; dGiveup += 0.5; dSynergy -= 0.5; dCounsel += 6;
                    notes.push(this._L('3-year Iberian price-coordination restriction: targeted, time-bound, preserves the geographic-market argument.', 'Restricción de coordinación de precios en Iberia por 3 años: focalizada, acotada en el tiempo y preserva el argumento de mercado geográfico.'));
                    branchSignal += 'B';
                } else {
                    dEu -= 22; dCounsel -= 6;
                    notes.push(this._L('No EU commitment leaves Kalogridaki without a graceful win; the formal RFR window in week 16 will harden.', 'Sin compromiso ante la UE, Kalogridaki se queda sin una victoria digna; la ventana formal de requerimiento de la semana 16 se endurecerá.'));
                    branchSignal += 'C';
                }
                if (d.overlay === 'mfn_5y') {
                    dCade += 6; dGiveup += 1.8;
                    notes.push(this._L('5-year MFN with monitoring trustee aligns with CADE Res 16/2017 and the 2008 EU Remedies Notice paras 117-127.', 'Cláusula de nación más favorecida a 5 años con administrador de vigilancia: alineada con la Res. 16/2017 del CADE y con la Comunicación de remedios de la UE de 2008, párrafos 117-127.'));
                    branchSignal += 'B';
                } else if (d.overlay === 'mfn_3y') {
                    dCade += 3; dGiveup += 1.2;
                } else {
                    dCade -= 5;
                    notes.push(this._L('No behavioural overlay leaves CADE without belt-and-braces; single point of failure on the structural fix.', 'Sin capa de conducta, el CADE se queda sin doble cinturón: punto único de fallo sobre el remedio estructural.'));
                }
            } else if (round === 3) {
                if (d.board_defense === 'portfolio_reframe') {
                    dChair += 22; dBoard += 16;
                    notes.push(this._L('Portfolio-rationalisation reframe lands with Manuel: sub-scale wholesale at 5.5x EBITDA is value-accretive against group ROIC.', 'El reencuadre como racionalización de cartera convence a Manuel: un mayorista subescala a 5,5 veces EBITDA suma valor frente al ROIC del grupo.'));
                    branchSignal += 'B';
                } else if (d.board_defense === 'numbers_first') {
                    dChair += 8; dBoard += 6;
                    notes.push(this._L('Pure numbers register works on Esther but Manuel reads it as defensive; chair pressure persists.', 'El registro puramente numérico funciona con Esther, pero Manuel lo lee como defensivo; la presión de la Presidencia persiste.'));
                } else {
                    dChair -= 8; dBoard -= 6;
                    notes.push(this._L('Leading with legal risk to a Chair who treats antitrust as a tax invites pushback.', 'Abrir con el riesgo legal ante una Presidencia que ve la defensa de la competencia como un impuesto invita al rechazo.'));
                }
                if (d.counsel_strategy === 'hold_eu_line') {
                    dCounsel += 14; dEu += 4; dCade += 4;
                    notes.push(this._L('Holding the geographic-market line with Vacher-Lamoureux preserves room to escalate at the State-of-Play meeting (week 18); pre-mandated buyer search reassures Caldas-Bittencourt.', 'Sostener la línea de mercado geográfico con Vacher-Lamoureux preserva margen para escalar en la reunión de estado de situación de la semana 18; la búsqueda de comprador pre-mandatada tranquiliza a Caldas-Bittencourt.'));
                    branchSignal += 'B';
                } else if (d.counsel_strategy === 'concede_vacher') {
                    dCounsel -= 4; dEu += 6; dGiveup += 4; dSynergy -= 4;
                    notes.push(this._L('Conceding to Vacher-Lamoureux early invites broader concessions across the case.', 'Ceder pronto ante Vacher-Lamoureux invita a concesiones más amplias en todo el expediente.'));
                    branchSignal += 'A';
                } else {
                    dCounsel -= 8; dCade -= 6;
                    notes.push(this._L('Deferring buyer search creates the fire-sale exposure Caldas-Bittencourt explicitly flagged.', 'Aplazar la búsqueda de comprador crea la exposición a venta forzada que Caldas-Bittencourt señaló de forma explícita.'));
                }
                if (d.coordination === 'full_icn') {
                    dCade += 6; dEu += 6; dCounsel += 4;
                    notes.push(this._L('ICN-style staff coordination with confidentiality waiver mirrors the 2018 Recommended Practices update.', 'La coordinación técnica al estilo de la Red Internacional de Competencia con renuncia de confidencialidad replica la actualización de prácticas recomendadas de 2018.'));
                    branchSignal += 'B';
                } else if (d.coordination === 'parallel_only') {
                    notes.push(this._L('Parallel filings without staff coordination is the minimum; jurisdictional-drift risk persists.', 'Notificaciones paralelas sin coordinación técnica es el mínimo; persiste el riesgo de deriva entre jurisdicciones.'));
                } else {
                    dCade -= 3; dEu -= 3;
                    notes.push(this._L('Counsel-only coordination misses the procedural alignment Kalogridaki and Bevilacqua-Moraes expect.', 'La coordinación solo entre abogados pierde la alineación procedimental que esperan Kalogridaki y Bevilacqua-Moraes.'));
                }
            }

            ds.cadeClearance = Math.max(0, Math.min(100, ds.cadeClearance + dCade));
            ds.euClearance = Math.max(0, Math.min(100, ds.euClearance + dEu));
            ds.ebitdaGiveup = Math.max(0, ds.ebitdaGiveup + dGiveup);
            ds.synergyRetention = Math.max(0, Math.min(100, ds.synergyRetention + dSynergy));
            ds.boardAcceptance = Math.max(0, Math.min(100, ds.boardAcceptance + dBoard));
            ds.chairManuel = Math.max(0, Math.min(100, ds.chairManuel + dChair));
            ds.counselTrust = Math.max(0, Math.min(100, ds.counselTrust + dCounsel));

            var baseIRR = 18.0;
            ds.dealIRR = Math.max(0, baseIRR - (ds.ebitdaGiveup * 0.18));

            var overallClearance = (ds.cadeClearance + ds.euClearance) / 2;
            (Array.isArray(ds.clearanceHistory) ? ds.clearanceHistory : (ds.clearanceHistory = [])).push(Math.round(overallClearance));
            (Array.isArray(ds.ebitdaHistory) ? ds.ebitdaHistory : (ds.ebitdaHistory = [])).push(Number(ds.ebitdaGiveup.toFixed(1)));
            (Array.isArray(ds.synergyHistory) ? ds.synergyHistory : (ds.synergyHistory = [])).push(Math.round(ds.synergyRetention));
            (Array.isArray(ds.irrHistory) ? ds.irrHistory : (ds.irrHistory = [])).push(Number(ds.dealIRR.toFixed(2)));

            var aCount = (branchSignal.match(/A/g) || []).length;
            var bCount = (branchSignal.match(/B/g) || []).length;
            var cCount = (branchSignal.match(/C/g) || []).length;
            var dominant = 'B';
            if (aCount > bCount && aCount > cCount) dominant = 'A';
            else if (cCount > bCount && cCount > aCount) dominant = 'C';
            ds.branchAlignment = dominant;

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 600);

            ds.lastAnalysis = this._renderAnalysis(notes);
            var composite = this._composite(ds);
            ds.composite = composite;
            ds.overallScore = composite;
            // Platform score: the 0-100 composite that getPerformanceSummary reports as overallScore; the band label stays in performance.band
            ds.performance = Object.assign({}, (ds.performance && typeof ds.performance === 'object') ? ds.performance : {}, { band: this._band(composite), overallScore: composite });
            if (notes.length) {
                var headline = notes[0];
                setTimeout(function() {
                    if (window.mySimulation && window.mySimulation.uiManager) {
                        window.mySimulation.uiManager.showNotification(headline, 'info');
                    }
                }, 200);
            }

            return {
                period: state.currentPeriod,
                composite: composite,
                roundKey: ['diagnose', 'design', 'defend'][state.currentPeriod - 1],
                roundName: this._roundNames()[state.currentPeriod - 1],
                cadeClearance: ds.cadeClearance,
                euClearance: ds.euClearance,
                ebitdaGiveup: ds.ebitdaGiveup,
                synergyRetention: ds.synergyRetention,
                chairManuel: ds.chairManuel,
                counselTrust: ds.counselTrust,
                dealIRR: ds.dealIRR,
                branchSignal: branchSignal
            };
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(Math.max(period - 1, 0), 2);
            var tr = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };
            var n = Math.min(idx, 3) + 1;
            var b = {
                title: tr('brief_r' + n + '_title'),
                subtitle: tr('brief_r' + n + '_subtitle'),
                body: tr('brief_r' + n + '_body')
            };

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = b.title;
            var subEl = document.getElementById('briefingSubtitle');
            if (subEl) subEl.textContent = b.subtitle;
            var bodyEl = document.getElementById('briefingBody');
            if (bodyEl) bodyEl.textContent = b.body;

            for (var i = 1; i <= 3; i++) {
                var panel = document.getElementById('round' + i + 'Panel');
                if (panel) panel.style.display = (i === (idx + 1)) ? 'block' : 'none';
            }
                    this._applyEndState(period);
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cadeDisplay', 'domainState.cadeClearance', (v) => Math.round(v) + '%');
            uiManager.bind('euDisplay', 'domainState.euClearance', (v) => Math.round(v) + '%');
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaGiveup', (v) => '$' + Number(v).toFixed(1) + 'M');
            uiManager.bind('synergyDisplay', 'domainState.synergyRetention', (v) => Math.round(v) + '%');
            uiManager.bind('chairDisplay', 'domainState.chairManuel', (v) => Math.round(v) + '/100');
            uiManager.bind('counselDisplay', 'domainState.counselTrust', (v) => Math.round(v) + '/100');
            uiManager.bind('irrDisplay', 'domainState.dealIRR', (v) => Number(v).toFixed(1) + '%');
            // Repaint the translated briefing when the player switches language
            var self = this;
            var fw = window.mySimulation;
            if (!this._langHooked && fw && fw.eventBus && typeof fw.eventBus.on === 'function') {
                this._langHooked = true;
                fw.eventBus.on('language:changed', function() {
                    try { self._updateBriefing(window.mySimulation.state); } catch (e) {}
                });
            }
        }

        _tr(key) {
            try { return (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t(key) : key; }
            catch (e) { return key; }
        }

        getChartConfig() {
            return {
                clearanceChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._tr('chart_ds_clearance'),
                                data: [],
                                borderColor: '#0a1f3d',
                                backgroundColor: 'rgba(10,31,61,0.12)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: this._tr('chart_ds_synergy'),
                                data: [],
                                borderColor: '#166534',
                                backgroundColor: 'rgba(22,101,52,0.08)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: this._tr('chart_ds_irr'),
                                data: [],
                                borderColor: '#c9a961',
                                backgroundColor: 'rgba(201,169,97,0.1)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: false },
                            legend: { position: 'bottom', labels: { color: '#1a2744', font: { size: 11 } } }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 100,
                                position: 'left',
                                title: { display: true, text: this._tr('chart_axis_left'), color: '#0a1f3d' },
                                grid: { color: 'rgba(10,31,61,0.06)' }
                            },
                            y1: {
                                beginAtZero: true,
                                max: 25,
                                position: 'right',
                                title: { display: true, text: this._tr('chart_axis_irr'), color: '#c9a961' },
                                grid: { drawOnChartArea: false }
                            },
                            x: { grid: { color: 'rgba(10,31,61,0.06)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var arr = function(x) { return Array.isArray(x) ? x : (x || []); };
            var roundLabels = this._roundNames();
            var labels = arr(ds.clearanceHistory).map(function(_, i) { return roundLabels[i] || ('R' + (i + 1)); });
            return {
                clearanceChart: {
                    labels: labels,
                    datasets: [
                        { label: this._tr('chart_ds_clearance'), data: arr(ds.clearanceHistory) },
                        { label: this._tr('chart_ds_synergy'), data: arr(ds.synergyHistory) },
                        { label: this._tr('chart_ds_irr'), data: arr(ds.irrHistory) }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = (last && last.domainState) ? last.domainState : {};
            var cadeC = ds.cadeClearance || 0;
            var euC = ds.euClearance || 0;
            var giveup = ds.ebitdaGiveup || 0;
            var synergy = ds.synergyRetention || 0;
            var chair = ds.chairManuel || 0;
            var counsel = ds.counselTrust || 0;
            var branch = ds.branchAlignment || 'undetermined';

            var overall = (cadeC + euC) / 2;
            var composite = this._composite(ds);
            var band = this._band(composite);
            var branchKey = 'mixed';
            var performance = this._L('Phase II Risk', 'Riesgo de Fase II');
            var insights = [];

            if (overall >= 80 && synergy >= 85 && chair >= 65) {
                branchKey = 'hybrid_cleared';
                performance = this._L('Hybrid Cleared — Branch B Hold Path', 'Autorización híbrida — vía B de sostener la línea');
                insights.push(this._L('CADE clears Phase II week 26 with structural divestiture and MFN overlay; EU clears week 24 on the wider geographic-market frame plus the 3-year Iberian price-coordination commitment.', 'El CADE autoriza en Fase II la semana 26 con desinversión estructural y capa de nación más favorecida; la UE autoriza la semana 24 sobre el marco geográfico amplio más el compromiso de coordinación de precios en Iberia a 3 años.'));
                insights.push(this._L('91% synergy retention; deal IRR holds above the 14% group hurdle. Manuel signs the board paper.', 'Retención de sinergias del 91%; la TIR de la operación se mantiene por encima del umbral del grupo del 14%. Manuel firma el documento del Consejo.'));
            } else if (overall >= 70 && synergy < 85 && giveup > 12) {
                branchKey = 'over_remediated'; performance = this._L('Cleared but Over-Remediated — Branch A Concession Path', 'Autorizada pero sobre-remediada — vía A de concesión');
                insights.push(this._L('Heavier package over-cleared both regulators; deal IRR drops below the 14% group hurdle. Manuel approves under protest, citing the 2019 Lácteos Andinos memory.', 'Un paquete más pesado sobre-autorizó ante ambos reguladores; la TIR cae por debajo del umbral del grupo del 14%. Manuel aprueba bajo protesta, invocando el recuerdo de Lácteos Andinos de 2019.'));
            } else if (overall < 55 && synergy >= 95) {
                branchKey = 'high_risk'; performance = this._L('High-Risk Refusal — Branch C Push Path', 'Rechazo de alto riesgo — vía C de forzar');
                insights.push(this._L('Behavioural-only package preserved synergy thesis; Caldas-Bittencourt assigns CADE failure probability 60-70%. Phase II prohibition or a forced last-minute structural divestiture is now the live scenario.', 'El paquete solo de conducta preservó la tesis de sinergias; Caldas-Bittencourt asigna al CADE una probabilidad de fracaso del 60-70%. La prohibición en Fase II o una desinversión estructural forzada de última hora es ahora el escenario vivo.'));
            } else {
                branchKey = 'mixed'; performance = this._L('Mixed Outcome — No Defined Branch', 'Resultado mixto — sin vía definida');
                insights.push(this._L('Package neither hits the optimal hybrid frontier nor commits to a defined branch. Reassess market-definition stance and remedy sizing before the CADE deadline.', 'El paquete ni alcanza la frontera híbrida óptima ni se compromete con una vía definida. Revisa la postura de definición de mercado y el dimensionamiento de remedios antes del plazo del CADE.'));
            }

            if (chair < 50) insights.push(this._L('Chair Manuel signalled rejection at the read-out; the board paper needs to lead with portfolio rationalisation, not legal risk.', 'El presidente Manuel señaló rechazo en la lectura; el documento del Consejo debe abrir con racionalización de cartera y no con riesgo legal.'));
            if (counsel < 50) insights.push(this._L('Outside counsel alignment slipped; Brevaine and Fontelar need a unified Phase II strategy memo before the CADE filing.', 'La alineación con los despachos externos se deterioró; Brevaine y Fontelar necesitan un memorando unificado de estrategia de Fase II antes de la notificación al CADE.'));
            if (giveup > 14) insights.push(this._L('EBITDA give-up exceeds the comparator-precedent envelope (Granvel/Calcaris, Brauhart/Lupulon); auditor scrutiny on synergy retention numbers is likely.', 'La cesión de EBITDA supera el rango de los precedentes comparables (Granvel/Calcaris, Brauhart/Lupulon); es probable el escrutinio del auditor sobre las cifras de retención de sinergias.'));

            return {
                cadeClearance: Math.round(cadeC),
                euClearance: Math.round(euC),
                ebitdaGiveup: Number(giveup.toFixed(1)),
                synergyRetention: Math.round(synergy),
                chairManuel: Math.round(chair),
                counselTrust: Math.round(counsel),
                dealIRR: Number(ds.dealIRR) || 0,
                branchAlignment: branch,
                branchKey: branchKey,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: band,
                performanceKey: band,
                performanceLabel: performance,
                branchLabel: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var score = (s.overallScore != null) ? s.overallScore : 0;
            var head = this._L('War-Room Verdict', 'Veredicto de la sala de crisis');
            var lbl = {
                score: this._L('Overall score', 'Puntuación global'),
                branch: this._L('Outcome branch', 'Vía de resultado'),
                cade: this._L('CADE clearance likelihood', 'Probabilidad de autorización CADE'),
                eu: this._L('EU clearance likelihood', 'Probabilidad de autorización UE'),
                syn: this._L('Synergy retention', 'Retención de sinergias'),
                give: this._L('EBITDA give-up', 'Cesión de EBITDA'),
                irr: this._L('Deal IRR', 'TIR de la operación'),
                chair: this._L('Chair confidence', 'Confianza de la Presidencia'),
                next: this._L('What to take away', 'Qué llevarte')
            };
            var rows = ''
                + '<li><strong>' + lbl.score + ':</strong> ' + score + '/100</li>'
                + '<li><strong>' + lbl.branch + ':</strong> ' + (s.branchLabel || s.performanceLabel || '') + '</li>'
                + '<li><strong>' + lbl.cade + ':</strong> ' + (s.cadeClearance != null ? s.cadeClearance : '-') + '%</li>'
                + '<li><strong>' + lbl.eu + ':</strong> ' + (s.euClearance != null ? s.euClearance : '-') + '%</li>'
                + '<li><strong>' + lbl.syn + ':</strong> ' + (s.synergyRetention != null ? s.synergyRetention : '-') + '%</li>'
                + '<li><strong>' + lbl.give + ':</strong> ' + (s.ebitdaGiveup != null ? s.ebitdaGiveup : '-') + '%</li>'
                + '<li><strong>' + lbl.irr + ':</strong> ' + (s.dealIRR != null ? Number(s.dealIRR).toFixed(1) : '-') + '%</li>'
                + '<li><strong>' + lbl.chair + ':</strong> ' + (s.chairManuel != null ? s.chairManuel : '-') + '/100</li>';
            var tips = (s.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '<div class="cade-eu-sim-complete"><h3>' + head + '</h3><ul>' + rows + '</ul>'
                 + '<h4>' + lbl.next + '</h4><ul>' + tips + '</ul></div>';
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.cadeClearance < 40) return window.mySimulation.t('hint_cade_low');
            if (results.euClearance < 40) return window.mySimulation.t('hint_eu_low');
            if (results.ebitdaGiveup > 13) return window.mySimulation.t('hint_giveup_high');
            if (results.chairManuel < 50) return window.mySimulation.t('hint_chair_low');
            if (results.counselTrust < 50) return window.mySimulation.t('hint_counsel_low');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundName',         label: 'Round',     i18nKey: 'col_round' },
                { key: 'results.cadeClearance',     label: 'CADE %',    i18nKey: 'col_cade',    formatter: (v) => Math.round(v) + '%' },
                { key: 'results.euClearance',       label: 'EU %',      i18nKey: 'col_eu',      formatter: (v) => Math.round(v) + '%' },
                { key: 'results.ebitdaGiveup',      label: 'Give-up',   i18nKey: 'col_giveup',  formatter: (v) => '$' + Number(v).toFixed(1) + 'M' },
                { key: 'results.synergyRetention',  label: 'Synergy',   i18nKey: 'col_synergy', formatter: (v) => Math.round(v) + '%' },
                { key: 'results.chairManuel',       label: 'Chair',     i18nKey: 'col_chair',   formatter: (v) => Math.round(v) + '/100' },
                { key: 'results.dealIRR',           label: 'IRR',       i18nKey: 'col_irr',     formatter: (v) => Number(v).toFixed(1) + '%' }
            ];
        }

